"""Single registry of every ECHOS component: what it is, what it owns, what it consumes / emits, how it fails. Served by GET /api/components and
documented in docs/COMPONENTS.md. kind: detector (senses, never decides), agent (goal-driven, uses tools, acts), infra (keeps things running)."""
from __future__ import annotations

COMPONENTS = [
    {"id": "quality", "name": "Data Quality gate", "kind": "detector", "worker": True,
     "role": "Checks that the data can be trusted before anything is scored: ranges, duplicates, gaps in the readings, freshness.",
     "inputs": "raw vitals events", "outputs": "quality verdict per patient-day (never imputes)",
     "on_failure": "data passes through marked 'quality unchecked'; the day can never be NORMAL",
     "never": "fill in missing values"},
    {"id": "health_monitoring", "name": "Vitals detector", "kind": "detector", "worker": True,
     "role": "Compares blood pressure and heart rate with the person's own usual (with SHAP explanations).",
     "inputs": "cleaned vitals", "outputs": "flags with evidence (personal baseline, persistence)",
     "on_failure": "fixed vitals thresholds are used and the day is marked 'monitoring degraded'",
     "never": "decide a status or send anything"},
    {"id": "fall", "name": "Fall detector", "kind": "detector", "worker": True,
     "role": "Detects a fall in a 2.5 s accelerometer window and checks for inactivity afterwards. Independent of the other detectors.",
     "inputs": "accelerometer windows", "outputs": "fall probability + inactivity evidence",
     "on_failure": "the supervisor restarts it; a fall that arrives meanwhile is delayed, not lost",
     "never": "use TIHM (it has no falls); decide an alert"},
    {"id": "triage", "name": "Triage agent", "kind": "agent", "worker": False,
     "role": "Turns detector outputs into one status (Normal / Changed-monitor / Urgent) with plain if-then rules and opens the case.",
     "inputs": "detector outputs", "outputs": "status, reasons, case",
     "on_failure": "a day with missing detector output is a data gap, never Normal",
     "never": "use a learned model or an LLM to decide"},
    {"id": "planner", "name": "Team Planner", "kind": "infra", "worker": False,
     "role": "Right after Triage, decides which of the four agents this case needs (and so how many) and writes one plain sentence of why per agent. One ratio r = the highest detector score over its own alert threshold, one cutoff theta chosen by a call budget: a fired rule adds the Investigator and the Care Coordinator (owner of an urgent alert); no rule but r above theta (a near miss) adds only a short watch file from the Investigator; otherwise only Triage and a template report.",
     "inputs": "triage decision + detector outputs", "outputs": "team plan (agents, size, r, theta, LLM request ceiling, reasons) on the bus and GET /api/patients/{id}/team-plan",
     "on_failure": "the case goes on with the fixed pipeline; an alert never waits for it",
     "never": "change the status, delay or suppress an alert, or use a model or an LLM"},
    {"id": "investigator", "name": "Case Investigator agent", "kind": "agent", "worker": False,
     "role": "For every non-Normal case, plans and runs up to 6 checks (case history, agreement between detectors, data caveats and two computed on the person's own past: trend of the readings, earlier deviation days with recorded events) and writes the case file.",
     "inputs": "triage decision + detector outputs + history", "outputs": "case file: headline, evidence level, supports, context (trend), caveats, next checks, trace of steps",
     "on_failure": "the case still goes on without a case file",
     "never": "change the status or give medical advice"},
    {"id": "coordinator", "name": "Care Coordinator agent", "kind": "agent", "worker": False,
     "role": "Owns every alert until someone acts: tracks delivery, waits for acknowledgement, escalates to a second contact, opens check-in and review tasks.",
     "inputs": "alerts, outbox, acknowledgements (web button or the signed e-mail link), case history", "outputs": "alert states, escalations, care tasks",
     "on_failure": "alerts are already sent by the dispatcher; only escalation and tasks pause until it restarts (state is in the database)",
     "never": "delay or suppress the first alert"},
    {"id": "report", "name": "Report agent", "kind": "agent", "worker": False,
     "role": "Writes the daily caregiver report and the weekly clinician PDF from the case file; the LLM is optional and always checked by a non-LLM validator.",
     "inputs": "case file, facts, retrieved guidance", "outputs": "daily report, weekly PDF, provenance",
     "on_failure": "a template report is used",
     "never": "decide an emergency or put an LLM on the alert path"},
    {"id": "supervisor", "name": "Supervisor", "kind": "infra", "worker": False,
     "role": "Replay mode: starts the three detector workers, watches their heartbeats and restarts dead ones (in live mode the detectors run inside the live processor).",
     "inputs": "heartbeats", "outputs": "restarts", "on_failure": "if the process holding it dies, the watchdog restarts that process", "never": "touch data"},
    {"id": "watchdog", "name": "Watchdog", "kind": "infra", "worker": True,
     "role": "Keeps the runtime process (supervisor, triage, live processor, Care Coordinator, emulator) alive: restarts it when it exits or stops reporting, with backoff.",
     "inputs": "the runtime's liveness signal and exit status", "outputs": "runtime restarts (restart_log)", "on_failure": "the runtime runs unsupervised until the watchdog is started again (an OS service manager can do that: templates in scripts/service/, not installed); nothing is lost, state is in SQLite", "never": "touch data or decide anything"},
]
BY_ID = {c["id"]: c for c in COMPONENTS}
